import{_ as e,o as t,c as l,a3 as p}from"./chunks/framework.DdpBa4_E.js";const n=JSON.parse('{"title":"常见问题解答","description":"","frontmatter":{},"headers":[],"relativePath":"books/career-guide/01-常见问题解答.md","filePath":"books/career-guide/01-常见问题解答.md","lastUpdated":1781445373000}'),a={name:"books/career-guide/01-常见问题解答.md"};function c(r,o,b,u,k,q){return t(),l("div",null,[...o[0]||(o[0]=[p('<h1 id="常见问题解答" tabindex="-1">常见问题解答 <a class="header-anchor" href="#常见问题解答" aria-label="Permalink to &quot;常见问题解答&quot;">​</a></h1><p>方法论往往看起来简单，但实际操作时遇到的问题总是千奇百怪。所以这里把我之前在微博问答中回答过的一些相对典型的问题整理出来，供大家参考。</p><p><strong>A：初级程序员，如何建立自己工作之余的学习规划。我是花大部分时间到读技术方面的书籍还是花更多的时间在开拓视野的书籍？</strong></p><blockquote><p>Q：对于程序员来讲，通常不是书读的太少，而是代码写的太少。所以我觉得对于初级程序员来讲，最好的学习规划是去写一个实用的、和工作相关的开源小项目或者可以发布到市场的独立小软件。</p></blockquote><blockquote><p>如果在写这个小项目的过程中，你遇到了问题，再带着这些问题去看其他开源项目的代码，或者去读相关的论文和技术书籍，你的成长会比单纯的去读书要快得多。</p></blockquote><blockquote><p>当我刚学完PHP的时候，我读了很多技术书，比如设计模式，比如敏捷开发，这些书都非常的不错，但是他们很难直接提升我的技术能力，而我用两个月的业余时间写完一个CMS时，回过头看，发现成长比过去一年都多。</p></blockquote><p><strong>A：Easy老师您好。我大学毕业两年了，现在在北京一家国企上班，想利用业余时间学习编程。想请教您三个问题： 1.我现在只是单纯想学，还不知道究竟能派上什么用场，想的是也许边学边能发现用处，但毕竟工作性质与码农毫不沾边，像我这种情况，您觉得究竟有无学的必要呢？ 2.周围有人推荐我从Python学起，有人推荐我从Ruby on Rails开始，众说纷纭，您的观点呢？ 3.关于学习方法。纯靠看书+自己摸索，我觉得对我这种纯小白来说难度太大，“从0开始学习编程”，您有推荐的学习方法吗？</strong></p><blockquote><p>一</p></blockquote><blockquote><p>我觉得你首先要弄明白的是你为什么要来学习编程，这是非常重要的。如果你有很强烈的创造欲望，或者需要持续编码的场景，再投入精力去学会比较好。不是说编程有多难，你学不会，而是说如果你只是学会，但是你不经常去使用的话，那么很快就会慢慢的忘掉。我学过Java，也学过Python，还学过Rails。刚学完的时候还能写一些小程序，但过上一两年很快就忘掉了。即使没有忘，以这行业现在的发展速度，可能你休个长假回来，发现好多项目依赖的组件都变了。😂</p></blockquote><blockquote><p>总而言之，就是如果你确定要来学习编程，就要想办法把它坚持下去，一直写一直用，否则的话还不如干脆就不要学了，省下时间去做一些更有意思的事情。比如逛街吃饭看电影🍲。</p></blockquote><blockquote><p>二</p></blockquote><blockquote><p>具体学习什么语言，主要看你想学来干什么。如果你想搞人工智能的话，Python会比较好；如果你想做云计算的话，GO就是首选；如果你要写APP当然是Swift；如果你想做Web的话，那就去学JavaScript；如果你想尽快找到份专职编程的工作，那么现在PHP缺得还是蛮多的。当然，关于语言每个人的看法都会不一样，以上这都是我的一些个人偏见。</p></blockquote><blockquote><p>三</p></blockquote><blockquote><p>如果你没有编程基础，那么你需要找一门语言把它的语法全部学会，然后逐渐的把它变成一个日常工具。</p></blockquote><blockquote><p>学习资料上的话，如果你英文比较好，可以找国外大学的语言教学视频。如果英文不太好，那么买国内的也行。</p></blockquote><blockquote><p>遇到问题以后，可以去搜stack overflow，绝大部分的技术问题在上边都有答案。</p></blockquote><blockquote><p>如果你不幸要做微信这种只有中国人才大量用的东西，那么记得去加入对应的开发交流群。</p></blockquote><blockquote><p>在这个基础上，再给自己定一些小任务。比如日常工作中，哪些重复劳动可以通过编写代码自动化掉。这样用以致学，想不学好都不行。</p></blockquote><p><strong>A：我零基础，非科班，想通过培训进入程序员行业，可行性大吗？互联网公司招聘对学校专业限制大吗？</strong></p><blockquote><p>如果你的培训质量足够的好，你学的也足够用心，能完成大部分互联网公司的日常开发工作，那么成为一个程序员问题不太大。</p></blockquote><blockquote><p>从我了解的情况来看，要找一份工作还是比较容易的（毕竟还有一堆的外包公司），但要找一份好工作，则是需要运气的（因为现在培训出来的程序员有点多了）。</p></blockquote><blockquote><p>不管是科班、培训还是自学，都是一个过程，最终看的还是你的能力，能干多少活，能管多少人。</p></blockquote><blockquote><p>专业一般不会成为门槛，但是会成为竞争优势。如果能力差不多的两个候选人，其中一个是计算机专业，那么他被优先录取的可能性会很高。</p></blockquote><p><strong>A：Easy老师，你好。我是一位工作刚好半年的前端开发工程师。最近觉得公司发展前景和培养新人方面很大欠缺，所以想换个工作。自认为已经完全可以胜任一年经验的工作，没想到企业好像都商量好一样，简历都石沉大海。您对工作刚满半年却想要换工作的新人怎么看待？希望得到您的指点。</strong></p><blockquote><p>我觉得有两点你需要想明白。</p></blockquote><blockquote><p>第一，通常来讲只有大公司，有比较完备的培养计划，但事实上完全不懂的新手是很难有机会进入大公司的，即使是应届毕业生，里面也是百里挑一。而小公司，基本都不会在新人上边投入大量的培养精力，一般给你分配一个师傅带着往前走就已经很不错了，所以，越是新手，培养这事儿越要靠自己，不能老指望公司。公司能培养你的时候，让公司培养你；公司不能培养你的时候，你要自己培养自己。</p></blockquote><blockquote><p>第二，在程序员这个行业是不论工龄的，半年经验和一年经验其实都是没啥经验。重点是你能写出什么样的代码、会用哪些框架、能处理哪些需求？在产品经理频繁变更的情况下，能否保持准时上线？是否有习惯写单元测试，如何保证你的代码质量。</p></blockquote><blockquote><p>所以，问题的中心又重新回到了你在这半年时间以来，你的能力提升了多少？你现在的能力，是否达到或者超过了你应聘公司的要求。</p></blockquote><blockquote><p>只要你自己能力彪悍，完全可以碾压其他工作更久的程序员。不服的话把代码摊开来，大家一比谁好谁坏，一目了然。这可能是这个行业最有意思，但又最残忍的地方。</p></blockquote><p>更多的问题，可以到我的<a href="https://weibo.com/1088413295/wenda?filter=3" target="_blank" rel="noreferrer">微博问答</a> 上边查看，绝大部分问题都已经超过三个月了，可以免费看。</p><h1 id="小册总结" tabindex="-1">小册总结 <a class="header-anchor" href="#小册总结" aria-label="Permalink to &quot;小册总结&quot;">​</a></h1><p>好了，这本小册子到这里也就结束了，非常感谢花上时间和金钱来阅读，也希望它能给你的职业带来新的气象。除了在掘金，大家还可以通过以下方式和我交流：</p><ul><li><p>微博：<a href="https://weibo.com/easy/" target="_blank" rel="noreferrer">@Easy</a> (主要活动场所)</p></li><li><p>Twitter：<a href="https://twitter.com/easychen" target="_blank" rel="noreferrer">@EasyChen</a> (主要分享二次元小姐姐)</p></li><li><p>博客：<a href="http://ftqq.com/%E7%80%9A%E6%B9%96%E5%90%AC%E9%9B%A8/002.adoc" target="_blank" rel="noreferrer">方糖气球</a> （有一些很不错的免费内容）</p></li><li><p>公众号：方糖君 （很少更新，因为懒🤣）</p><p><img src="https://user-gold-cdn.xitu.io/2017/11/10/7a8c1c717683bf4d6c7f4b87a0f31913" alt="" loading="lazy"></p></li></ul>',33)])])}const i=e(a,[["render",c]]);export{n as __pageData,i as default};
